from tasks_api.queries import TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _make_tasks():
    """Build a set of tasks for query testing."""
    return [
        Task(
            id=1, title="Alpha task", status=TaskStatus.PENDING,
            priority=TaskPriority.LOW, tags=[Tag("work")],
            created_at=datetime(2025, 5, 1, tzinfo=timezone.utc),
            due_at=datetime(2025, 5, 15, tzinfo=timezone.utc),  # overdue
        ),
        Task(
            id=2, title="Beta task", status=TaskStatus.DONE,
            priority=TaskPriority.HIGH, tags=[Tag("personal")],
            created_at=datetime(2025, 5, 2, tzinfo=timezone.utc),
            completed_at=datetime(2025, 5, 20, tzinfo=timezone.utc),
        ),
        Task(
            id=3, title="Gamma task", status=TaskStatus.PENDING,
            priority=TaskPriority.MEDIUM, tags=[Tag("work"), Tag("urgent")],
            created_at=datetime(2025, 5, 3, tzinfo=timezone.utc),
            due_at=datetime(2025, 7, 1, tzinfo=timezone.utc),  # not overdue
        ),
        Task(
            id=4, title="Delta task", status=TaskStatus.PENDING,
            priority=TaskPriority.HIGH, tags=[],
            created_at=datetime(2025, 5, 4, tzinfo=timezone.utc),
        ),
    ]


class TestFilterStatus:
    def test_pending(self):
        page = apply_query(_make_tasks(), TaskQuery(status=TaskStatus.PENDING), NOW)
        assert page.total == 3
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_done(self):
        page = apply_query(_make_tasks(), TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2


class TestFilterTag:
    def test_matching_tag(self):
        page = apply_query(_make_tasks(), TaskQuery(tag="work"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 3}

    def test_no_match(self):
        page = apply_query(_make_tasks(), TaskQuery(tag="nonexistent"), NOW)
        assert page.total == 0


class TestFilterSearch:
    def test_case_insensitive(self):
        page = apply_query(_make_tasks(), TaskQuery(search="ALPHA"), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_partial_match(self):
        page = apply_query(_make_tasks(), TaskQuery(search="task"), NOW)
        assert page.total == 4

    def test_whitespace_only_treated_as_none(self):
        page = apply_query(_make_tasks(), TaskQuery(search="   "), NOW)
        assert page.total == 4


