    def test_overdue_true(self):
        page = apply_query(_make_tasks(), TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_overdue_false(self):
        page = apply_query(_make_tasks(), TaskQuery(overdue=False), NOW)
        assert page.total == 3  # tasks 2,3,4 are not overdue


class TestSorting:
    def test_sort_by_title_asc(self):
        page = apply_query(_make_tasks(), TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_by_title_desc(self):
        page = apply_query(_make_tasks(), TaskQuery(sort="title", descending=True), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower, reverse=True)

    def test_sort_by_priority(self):
        page = apply_query(_make_tasks(), TaskQuery(sort="priority"), NOW)
        priorities = [TaskPriority.order_key(t.priority) for t in page.items]
        assert priorities == sorted(priorities)

    def test_sort_by_created_at(self):
        page = apply_query(_make_tasks(), TaskQuery(sort="created_at"), NOW)
        dates = [t.created_at for t in page.items]
        assert dates == sorted(dates)

    def test_sort_by_due_at(self):
        page = apply_query(_make_tasks(), TaskQuery(sort="due_at"), NOW)
        # Tasks with None due_at sort last
        assert page.items[-1].due_at is None or page.items[-2].due_at is None


